import { Injectable, NotFoundException } from '@nestjs/common';
import { SupabaseService } from '../supabase/supabase.service';

@Injectable()
export class EmpresasService {
  constructor(private supabase: SupabaseService) {}

  private gerarSlug(name: string): string {
    return name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').trim();
  }

  async listar(apenasAtivo?: boolean) {
    let query = this.supabase.client
      .from('restaurants')
      .select('id, name, address, logo_url, comissao_pct, user_id, slug, bloqueado, custom_domain, custom_domain_status, custom_domain_solicitado_em, custom_domain_motivo_recusa, modulo_delivery, modulo_salao, created_at')
      .order('name');

    const { data, error } = await query;
    if (error) throw error;
    return { empresas: data, total: data?.length ?? 0 };
  }

  async buscar(id: number) {
    const { data, error } = await this.supabase.client
      .from('restaurants')
      .select('id, name, address, logo_url, business_hours, payment_config, comissao_pct, user_id, slug, modulo_delivery, modulo_salao, created_at')
      .eq('id', id)
      .maybeSingle();

    if (error) throw error;
    if (!data) throw new NotFoundException(`Empresa ${id} não encontrada`);

    const { data: metricas } = await this.supabase.client
      .from('orders')
      .select('id, total, status')
      .eq('restaurant_id', id);

    const entregues = (metricas ?? []).filter((p) => p.status === 'delivered');
    const faturamento = entregues.reduce((acc, p) => acc + (p.total ?? 0), 0);

    return {
      empresa: data,
      metricas: {
        total_pedidos: metricas?.length ?? 0,
        pedidos_entregues: entregues.length,
        faturamento,
        comissao_acumulada: parseFloat((faturamento * (data.comissao_pct / 100)).toFixed(2)),
      },
    };
  }

  async criar(body: {
    name: string;
    address?: string;
    logo_url?: string;
    comissao_pct?: number;
    user_id?: string;
    slug?: string;
    modulo_delivery?: boolean;
    modulo_salao?: boolean;
  }) {
    const { data, error } = await this.supabase.client
      .from('restaurants')
      .insert({
        name: body.name,
        address: body.address ?? null,
        logo_url: body.logo_url ?? null,
        comissao_pct: body.comissao_pct ?? 5.0,
        user_id: body.user_id || null,
        slug: body.slug || this.gerarSlug(body.name),
        modulo_delivery: body.modulo_delivery ?? true,
        modulo_salao: body.modulo_salao ?? false,
      })
      .select()
      .single();

    if (error) throw error;
    return data;
  }

  async atualizar(id: number, body: Partial<{
    name: string;
    address: string;
    logo_url: string;
    comissao_pct: number;
    business_hours: object;
    payment_config: object;
    user_id: string;
    modulo_delivery: boolean;
    modulo_salao: boolean;
  }>) {
    const payload: Record<string, any> = { ...body, updated_at: new Date().toISOString() };
    if ('user_id' in payload && !payload.user_id) payload.user_id = null;

    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update(payload)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    if (!data) throw new NotFoundException(`Empresa ${id} não encontrada`);
    return data;
  }

  async bloquear(id: number, bloqueado: boolean) {
    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update({ bloqueado, updated_at: new Date().toISOString() })
      .eq('id', id)
      .select('id, name, bloqueado')
      .single();
    if (error) throw error;
    return data;
  }

  async atenderSolicitacaoDominio(id: number) {
    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update({
        custom_domain_status: null,
        custom_domain_motivo_recusa: null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .select('id, name, custom_domain, custom_domain_status')
      .maybeSingle();

    if (error) throw error;
    if (!data) throw new NotFoundException(`Empresa ${id} não encontrada`);
    return data;
  }

  async recusarSolicitacaoDominio(id: number, motivo: string) {
    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update({
        custom_domain_status: 'recusado',
        custom_domain_motivo_recusa: motivo || 'Não especificado',
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .select('id, name, custom_domain, custom_domain_status, custom_domain_motivo_recusa')
      .maybeSingle();

    if (error) throw error;
    if (!data) throw new NotFoundException(`Empresa ${id} não encontrada`);
    return data;
  }

-- Migra tipo TEXT → tags TEXT[] nos produtos
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS tags TEXT[] NOT NULL DEFAULT '{}';

-- Migra valores existentes (ignora 'normal' e 'combo' — combo vira entidade própria)
UPDATE public.products
SET tags = CASE
  WHEN tipo IN ('mais_vendido', 'promo') THEN ARRAY[tipo]
  ELSE '{}'
END
WHERE tipo IS NOT NULL;

ALTER TABLE public.products DROP COLUMN IF EXISTS tipo;

-- Combos: entidade separada por restaurante
CREATE TABLE IF NOT EXISTS public.combos (
  id          BIGSERIAL PRIMARY KEY,
  restaurant_id BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  description TEXT,
  price       DECIMAL(10,2) NOT NULL,
  preco_promo DECIMAL(10,2),
  image_url   TEXT,
  is_active   BOOLEAN NOT NULL DEFAULT true,
  destaque    BOOLEAN NOT NULL DEFAULT false,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.combo_items (
  id         BIGSERIAL PRIMARY KEY,
  combo_id   BIGINT NOT NULL REFERENCES public.combos(id) ON DELETE CASCADE,
  product_id BIGINT NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  quantity   INTEGER NOT NULL DEFAULT 1,
  UNIQUE (combo_id, product_id)
);

-- RLS combos
ALTER TABLE public.combos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.combo_items ENABLE ROW LEVEL SECURITY;

CREATE POLICY "publico_ver_combos" ON public.combos FOR SELECT USING (is_active = true);
CREATE POLICY "owner_gerir_combos" ON public.combos USING (
  restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
);
CREATE POLICY "publico_ver_combo_items" ON public.combo_items FOR SELECT USING (true);
CREATE POLICY "owner_gerir_combo_items" ON public.combo_items USING (
  combo_id IN (
    SELECT c.id FROM public.combos c
    JOIN public.restaurants r ON r.id = c.restaurant_id
    WHERE r.user_id = auth.uid()
  )
);

CREATE INDEX IF NOT EXISTS idx_combos_restaurant ON public.combos(restaurant_id);
CREATE INDEX IF NOT EXISTS idx_combo_items_combo ON public.combo_items(combo_id);
CREATE INDEX IF NOT EXISTS idx_combo_items_product ON public.combo_items(product_id);

-- Fase: Página de vendas profissional

-- Configurações visuais do restaurante
ALTER TABLE public.restaurants
  ADD COLUMN IF NOT EXISTS aparencia JSONB DEFAULT '{}'::jsonb;

-- Tipo do produto: normal, promo (com desconto), combo
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS tipo TEXT DEFAULT 'normal'
    CHECK (tipo IN ('normal', 'promo', 'combo'));

ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS preco_promo NUMERIC(10,2);

ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS destaque BOOLEAN DEFAULT false;

-- Índice para busca por tipo
CREATE INDEX IF NOT EXISTS idx_products_tipo ON public.products(tipo);
CREATE INDEX IF NOT EXISTS idx_products_destaque ON public.products(destaque);

-- Tipos de estabelecimento (restaurante, farmácia, mat. construção etc).
-- Populada pelo dev via migration — sem CRUD de admin nessa fase.
CREATE TABLE IF NOT EXISTS public.establishment_types (
    id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    icon_name  TEXT NOT NULL DEFAULT 'Store',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO public.establishment_types (name, icon_name)
VALUES
    ('Restaurante',          'UtensilsCrossed'),
    ('Farmácia',             'Pill'),
    ('Material de Construção', 'HardHat')
ON CONFLICT (name) DO NOTHING;

ALTER TABLE public.establishment_types ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = 'public' AND tablename = 'establishment_types'
          AND policyname = 'establishment_types_public_read'
    ) THEN
        EXECUTE 'CREATE POLICY "establishment_types_public_read" ON public.establishment_types FOR SELECT USING (true)';
    END IF;
END $$;

-- Vincula cada restaurante a um tipo. Default = "Restaurante", pra não quebrar cadastros existentes.
ALTER TABLE public.restaurants
    ADD COLUMN IF NOT EXISTS type_id BIGINT REFERENCES public.establishment_types(id);

UPDATE public.restaurants
SET type_id = (SELECT id FROM public.establishment_types WHERE name = 'Restaurante')
WHERE type_id IS NULL;

-- Módulo Salão: mesas físicas do restaurante (modo "por mesa")
CREATE TABLE IF NOT EXISTS public.mesas (
  id             BIGSERIAL PRIMARY KEY,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  numero         INTEGER NOT NULL,
  nome           TEXT,
  status         TEXT NOT NULL DEFAULT 'livre'
                 CHECK (status IN ('livre','ocupada','aguardando_pagamento')),
  created_at     TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (restaurant_id, numero)
);

CREATE INDEX idx_mesas_restaurant ON public.mesas (restaurant_id);

ALTER TABLE public.mesas ENABLE ROW LEVEL SECURITY;

CREATE POLICY mesas_owner ON public.mesas
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

